def _make_instance(**overrides):
    """Build a minimal instance dict with sensible defaults."""
    base = {"repo": "django/django", "instance_id": "test-0", "base_commit": "abc123"}
    base.update(overrides)
    return base


def _inst(repo):
    return _make_instance(repo=repo)


