@pytest.mark.parametrize("text, repo, expected", DOCSTRING_CASES,
    ids=[f"docstrip-{i}" for i in range(215)])
class TestDocstringStripping:
    """Triple double-quote docstrings are removed before pattern matching."""
    def test_docstring_stripping(self, text, repo, expected, capsys):
        """Verify docstring content is stripped and correct version extracted."""
        result = _find_version_in_text(text, _inst(repo))
        assert result == expected


