@pytest.mark.parametrize("text, expected", SKBIO_NONE,
    ids=[f"skbio-n-{i}" for i in range(14)])
class TestScikitBioNoMatch:
    """scikit-bio returns None for non-__version__ patterns."""
    def test_skbio_none(self, text, expected, capsys):
        """Verify scikit-bio returns None when pattern does not match."""
        result = _find_version_in_text(text, _inst("scikit-bio/scikit-bio"))
        assert result == expected


