# ── INTEGRATION TESTS ─────────────────────────────────────────────────


class TestIntegrationWithConstants:
    """Integration: _find_version_in_text uses MAP_REPO_TO_VERSION_PATTERNS correctly."""

    @pytest.mark.parametrize(
        "repo",
        list(MAP_REPO_TO_VERSION_PATTERNS.keys()),
        ids=[r.replace("/", "_") for r in MAP_REPO_TO_VERSION_PATTERNS.keys()],
    )
    def test_every_repo_pattern_is_exercised(self, repo):
        """Each repo's first pattern matches at least one standard version string."""
        candidates = [
            '__version__ = "1.2.3"',
            "__version__ = '4.5.6'",
            "VERSION = (1, 2, 3)",
            "__version__ = version = '1.2.3'",
            "version_info = 1, 2,",
            'major = "3"\nminor = "2"',
            "1.2.3",
        ]
        found = False
        for text in candidates:
            result = _find_version_in_text(text, _inst(repo))
            if result is not None:
                found = True
                break
        if repo == "pyvista/pyvista":
            text = "version_info = 1, 2, 3,"
            result = _find_version_in_text(text, _inst(repo))
            found = result is not None
        assert found, f"No standard text matched any pattern for {repo}"

    def test_constants_patterns_not_modified_by_calls(self):
        """Calling _find_version_in_text does not mutate the MAP."""
        import copy
        original = copy.deepcopy(dict(MAP_REPO_TO_VERSION_PATTERNS))
        _find_version_in_text('__version__ = "1.0.0"', _inst("scikit-learn/scikit-learn"))
        _find_version_in_text('__version__ = "2.0.0"', _inst("pytest-dev/pytest"))
        _find_version_in_text("version_info = 1, 2,", _inst("pyvista/pyvista"))
        for repo in original:
            assert MAP_REPO_TO_VERSION_PATTERNS[repo] == original[repo]

    def test_generic_fallback_only_for_unknown_repos(self):
        """Known repos use MAP patterns, unknown repos use _GENERIC_VERSION_PATTERNS."""
        known = "scikit-learn/scikit-learn"
        unknown = "totally-unknown/lib"
        text = '__version__ = "9.8.7"'
        r1 = _find_version_in_text(text, _inst(known))
        r2 = _find_version_in_text(text, _inst(unknown))
        assert r1 is not None
        assert r2 is not None

    def test_docstring_stripping_then_pattern_match(self):
        """Integration: docstring removal + pattern matching work together."""
        text = '"""\n__version__ = "0.0.0"\n"""\n__version__ = "1.2.3"'
        result = _find_version_in_text(text, _inst("scikit-learn/scikit-learn"))
        assert result == "1.2.3"


class TestIntegrationPyvistaNetworkxSpecialPaths:
    """Integration: special-case repos through full flow."""

    def test_pyvista_full_flow(self):
        """pyvista: version_info line through special path."""
        text = "version_info = 0, 42, 1,"
        result = _find_version_in_text(text, _inst("pyvista/pyvista"))
        assert result is not None
        assert "." in result

    def test_networkx_full_flow_multigroup(self):
        """networkx: multi-group regex concatenation."""
        text = 'major = "3"\nminor = "2"'
        result = _find_version_in_text(text, _inst("networkx/networkx"))
        assert result == "3.2"

    def test_networkx_single_group_fallback(self):
        """networkx: single-group match uses standard path."""
        text = '__version__ = "3.2.1"'
        result = _find_version_in_text(text, _inst("networkx/networkx"))
        assert result is not None
        assert "3.2.1" in result


# ── END-TO-END TESTS ─────────────────────────────────────────────────


class TestEndToEndVersionExtraction:
    """E2E: simulate complete version extraction as get_version() would use it."""

    @pytest.mark.parametrize(
        "repo, file_content, expected",
        [
            ("scikit-learn/scikit-learn", '__version__ = "1.3.2"\n', "1.3.2"),
            ("pytest-dev/pytest", "__version__ = version = '7.4.0'\n", "7.4.0"),
            ("matplotlib/matplotlib", "__version__ = version = '3.8.0'\n", "3.8.0"),
            ("Qiskit/qiskit", "0.45.1", "0.45.1"),
            ("django/django", '__version__ = "4.2.7"\n', "4.2.7"),
            ("pallets/flask", '__version__ = "3.0.0"\n', "3.0.0"),
            ("psf/requests", '__version__ = "2.31.0"\n', "2.31.0"),
            ("pandas-dev/pandas", '__version__ = "2.1.3"\n', "2.1.3"),
        ],
        ids=["sklearn", "pytest", "mpl", "qiskit", "django", "flask", "requests", "pandas"],
    )
    def test_e2e_standard_repos(self, repo, file_content, expected):
        """E2E: text to version string."""
        result = _find_version_in_text(file_content, _inst(repo))
        assert result == expected

    def test_e2e_pyvista_realistic_init_file(self):
        """E2E: realistic pyvista __init__.py content."""
        content = "version_info = 0, 42, 1,\n__all__ = ['plot', 'Plotter']\n"
        result = _find_version_in_text(content, _inst("pyvista/pyvista"))
        assert result is not None

    def test_e2e_networkx_realistic_release_file(self):
        """E2E: realistic networkx release.py content."""
        content = 'import os\nimport re\n\nmajor = "3"\nminor = "2"\nmicro = "1"\n'
        result = _find_version_in_text(content, _inst("networkx/networkx"))
        assert result == "3.2"

    def test_e2e_scikit_bio_realistic_init(self):
        """E2E: realistic scikit-bio __init__.py."""
        content = '__version__ = "0.5.9"\n__all__ = ["Sequence", "DNA"]\n'
        result = _find_version_in_text(content, _inst("scikit-bio/scikit-bio"))
        assert result == "0.5.9"

    def test_e2e_unknown_repo_with_standard_init(self):
        """E2E: unknown repo using generic patterns."""
        content = '__version__ = "2.4.1"\n'
        result = _find_version_in_text(content, _inst("myorg/mylib"))
        assert result == "2.4.1"

    def test_e2e_unknown_repo_with_version_tuple(self):
        """E2E: unknown repo with VERSION tuple format."""
        content = 'VERSION = (1, 2, 3)\n__version__ = ".".join(map(str, VERSION))\n'
        result = _find_version_in_text(content, _inst("myorg/mylib"))
        assert result is not None

    def test_e2e_full_pipeline_multiple_repos(self):
        """E2E: process multiple repos sequentially."""
        test_cases = [
            ("scikit-learn/scikit-learn", '__version__ = "1.0.0"', True),
            ("numpy/numpy", '__version__ = "1.24.0"', True),
            ("scipy/scipy", '__version__ = "1.11.0"', True),
            ("unknown/repo", "# no version here", False),
            ("pyvista/pyvista", "version_info = 0, 42, 1,", True),
        ]
        results = {}
        for repo, text, should_find in test_cases:
            result = _find_version_in_text(text, _inst(repo))
            results[repo] = result
            if should_find:
                assert result is not None, f"Expected version for {repo}"
            else:
                assert result is None, f"Expected None for {repo}"
        assert len(results) == 5

    def test_e2e_docstring_heavy_file(self):
        """E2E: file with multiple docstrings, only real version survives."""
        content = '"""\nModule docstring.\n__version__ = "0.0.0"\nSome docs here.\n"""\n\n__version__ = "3.1.4"\n\ndef main():\n    pass\n'
        result = _find_version_in_text(content, _inst("scikit-learn/scikit-learn"))
        assert result == "3.1.4"


