class TestNullEmptyMissing:

    def test_none_text_returns_none(self):
        result = _find_version_in_text(None, _inst("django/django"))
        assert result is None

    def test_none_instance_raises_type_error(self):
        with pytest.raises(TypeError):
            _find_version_in_text("__version__ = '1.0'", None)

    def test_empty_dict_instance_raises_key_error(self):
        with pytest.raises(KeyError):
            _find_version_in_text("__version__ = '1.0'", {})

    def test_empty_string_text_returns_none(self):
        result = _find_version_in_text("", _inst("django/django"))
        assert result is None

    def test_missing_repo_key_raises_key_error(self):
        with pytest.raises(KeyError):
            _find_version_in_text("text", {"instance_id": "x"})


# ────────────────────────────────────────────────────────────
# Gap Coverage — D3: Type Coercion
# ────────────────────────────────────────────────────────────


class TestTypeCoercion:

    def test_int_text_raises_type_error(self):
        with pytest.raises(TypeError):
            _find_version_in_text(123, _inst("django/django"))

    def test_list_text_raises_type_error(self):
        with pytest.raises(TypeError):
            _find_version_in_text(["text"], _inst("x/y"))

    def test_int_instance_raises_type_error(self):
        with pytest.raises(TypeError):
            _find_version_in_text("text", 42)

    def test_string_instance_raises_type_error(self):
        with pytest.raises((TypeError, KeyError)):
            _find_version_in_text("text", "django/django")


