# Gap Coverage — D4/D9: String Edge Cases
# ────────────────────────────────────────────────────────────


class TestStringEdgeCases:

    def test_null_byte_in_text(self):
        result = _find_version_in_text(
            "__version__ = '1.2.3'\x00extra", _inst("django/django")
        )
        assert result == "1.2.3"

    def test_bom_prefix(self):
        result = _find_version_in_text(
            "\ufeff__version__ = '1.2.3'", _inst("django/django")
        )
        assert result == "1.2.3"

    def test_crlf_line_endings(self):
        result = _find_version_in_text(
            "__version__ = '1.2.3'\r\n", _inst("django/django")
        )
        assert result == "1.2.3"

    def test_tab_in_assignment(self):
        result = _find_version_in_text(
            "__version__\t=\t'1.2.3'", _inst("django/django")
        )
        assert result is None or result == "1.2.3"

    def test_very_long_text_with_version_at_end(self):
        padding = "# comment line\n" * 100_000
        text = padding + '\n__version__ = "1.2.3"'
        result = _find_version_in_text(text, _inst("django/django"))
        assert result == "1.2.3"

    def test_very_long_text_no_version(self):
        text = "x" * 100_000
        result = _find_version_in_text(text, _inst("django/django"))
        assert result is None

    def test_nested_quotes_in_text(self):
        text = "__version__ = '1.2.3'\nother = \"some value\""
        result = _find_version_in_text(text, _inst("django/django"))
        assert result == "1.2.3"


