class TestImportBehavior:

    def test_generic_version_patterns_are_valid_regex(self):
        import re
        from swefficiency.versioning.get_versions import _GENERIC_VERSION_PATTERNS

        for pattern in _GENERIC_VERSION_PATTERNS:
            compiled = re.compile(pattern)
            assert compiled is not None

    def test_map_patterns_all_compile(self):
        import re

        for repo, patterns in MAP_REPO_TO_VERSION_PATTERNS.items():
            for i, pattern in enumerate(patterns):
                try:
                    re.compile(pattern)
                except re.error as e:
                    pytest.fail(f"Pattern {i} for {repo!r} failed to compile: {e}")
